description:
Write functions that take and return **pointers**, without copying any of the ints:

```cpp
int* pickLarger(int* a, int* b);
bool sameObject(const int* a, const int* b);
int* firstNonNull(int* a, int* b, int* c);
```

- **pickLarger** returns whichever pointer points at the larger value; if the values are equal it returns `a`. If one of the two is `nullptr` it returns the other one, and if both are, `nullptr`.
- **sameObject** is true when both point at the same object (the same address), not when the values are merely equal. Two `nullptr`s count as the same.
- **firstNonNull** returns the first of its arguments that is not `nullptr`, or `nullptr` if all three are.

starter.solution.cpp:
int* pickLarger(int* a, int* b) { return nullptr; }
bool sameObject(const int* a, const int* b) { return false; }
int* firstNonNull(int* a, int* b, int* c) { return nullptr; }

solution.solution.cpp:
int* pickLarger(int* a, int* b)
{
    if (!a) return b;
    if (!b) return a;
    return *b > *a ? b : a;
}

bool sameObject(const int* a, const int* b)
{
    return a == b;
}

int* firstNonNull(int* a, int* b, int* c)
{
    if (a) return a;
    if (b) return b;
    return c;
}

unitTests:
TEST("pickLarger returns a pointer to the larger value") {
    int x{ 3 }, y{ 8 }, z{ 3 };
    CHECK(pickLarger(&x, &y) == &y);
    CHECK(pickLarger(&y, &x) == &y);
    CHECK(pickLarger(&x, &z) == &x);
    CHECK(pickLarger(&z, &x) == &z);
}
TEST("pickLarger with nullptr") {
    int x{ -5 };
    CHECK(pickLarger(nullptr, &x) == &x);
    CHECK(pickLarger(&x, nullptr) == &x);
    CHECK(pickLarger(nullptr, nullptr) == nullptr);
}
TEST("the result can be written through") {
    int x{ 10 }, y{ 20 };
    *pickLarger(&x, &y) = 0;
    CHECK_EQ(x, 10);
    CHECK_EQ(y, 0);
}
TEST("same object, not same value") {
    int a{ 5 }, b{ 5 };
    CHECK(sameObject(&a, &a));
    CHECK(!sameObject(&a, &b));
    CHECK(sameObject(nullptr, nullptr));
    CHECK(!sameObject(&a, nullptr));
}
TEST("first non-null") {
    int a{ 1 }, b{ 2 };
    CHECK(firstNonNull(nullptr, &b, &a) == &b);
    CHECK(firstNonNull(&a, &b, nullptr) == &a);
    CHECK(firstNonNull(nullptr, nullptr, &a) == &a);
    CHECK(firstNonNull(nullptr, nullptr, nullptr) == nullptr);
}

